import random
import time

class Player:
    def __init__(self):
        self.score = 0
        self.health = 100

    def attack(self):
        return random.randint(10, 20)

    def take_damage(self, damage):
        self.health -= damage
        if self.health < 0:
            self.health = 0

    def is_alive(self):
        return self.health > 0

class Enemy:
    def __init__(self):
        self.health = 50
        self.attack_power = random.randint(5, 15)

    def attack(self):
        return self.attack_power

    def is_alive(self):
        return self.health > 0

def game_loop():
    player = Player()
    enemy = Enemy()
