    print("You are fighting an enemy. Attack to win, but be careful of their attacks!\n")

    while player.is_alive() and enemy.is_alive():
        print(f"\nPlayer Health: {player.health} | Enemy Health: {enemy.health}")
        print(f"Player Score: {player.score}")

